// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testRegression_property() public {
        c.SetLogFile(address(0xdead));
        c.Initialized();
        bool ok;
        try c.SetMinSum(100) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
